def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]
    if n >= 2:
        prev_me, prev_opp = history[-2]
    else:
        prev_me, prev_opp = 'C', 'C'

    opp_d = 0
    my_d = 0
    for m, o in history:
        if m == 'D':
            my_d += 1
        if o == 'D':
            opp_d += 1

    opp_rate = 1 - (opp_d / n)
    w = min(n, 10)
    recent_d = 0
    for i in range(n - w, n):
        if history[i][1] == 'D':
            recent_d += 1

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    our_d_count = 0
    punish_count = 0
    for i in range(1, n):
        if history[i - 1][0] == 'D':
            our_d_count += 1
            if history[i][1] == 'D':
                punish_count += 1

    exploit = (our_d_count >= 1 and punish_count == 0 and opp_rate > 0.75 and recent_d <= 2)
    probe = (n == 30 and opp_d == 0 and my_d == 0)
    hostile = (
        opp_rate < 0.35
        or (n >= 5 and (opp_rate < 0.55 or recent_d >= max(5, int(w * 0.7))))
        or (recent_d == w and recent_d >= 2)
    )

    if last_opp == 'C':
        if exploit:
            return 'D'
        if probe:
            return 'D'
        if hostile:
            if recent_d <= 3 and opp_rate > 0.35 and my_d_streak >= 4:
                if rng.random() < 0.1:
                    return 'C'
            return 'D'
        return 'C'

    if exploit and opp_rate > 0.85 and opp_d_streak <= 2 and recent_d <= 3:
        return 'C'

    if hostile:
        early = min(n, 20)
        early_d = 0
        for i in range(early):
            if history[i][1] == 'D':
                early_d += 1
        if opp_rate > 0.3 and early_d <= max(1, early // 4):
            if my_d_streak >= 3 and recent_d <= 8:
                if rng.random() < 0.2:
                    return 'C'
        return 'D'

    if opp_rate > 0.75:
        if opp_d <= max(1, n // 6) and opp_d_streak <= 2 and recent_d <= 3:
            if last_me == 'D' or (prev_me == 'D' and prev_opp == 'C'):
                return 'C'
            return 'D'
        if opp_d_streak >= 3 or recent_d >= 4:
            if my_d_streak >= 2 and rng.random() < 0.5:
                return 'C'
            return 'D'
        return 'D'

    if last_me == 'C':
        return 'D'

    if opp_d_streak <= 2 and recent_d <= 4:
        if my_d_streak >= 2 or (prev_me == 'D' and prev_opp == 'C'):
            return 'C'
        return 'D'

    if my_d_streak >= 3 and opp_rate > 0.6:
        if rng.random() < 0.35:
            return 'C'

    return 'D'
